<template><view class="rpg-room" :style="viewportCss"><view v-if="snapshot" class="rpg-room__card"><button class="rpg-room__back" @click="leave">← 返回大厅</button><view class="rpg-room__header"><view><text>{{ snapshot.mode==='PK'?'多人PK':'合作进球' }}</text><strong>房间码 {{ snapshot.roomCode }}</strong></view><text>{{ snapshot.players.length }}/5人</text></view><view class="rpg-room__players"><view v-for="p in snapshot.players" :key="p.playerId"><text>{{ p.displayName }}{{ p.playerId===snapshot.hostPlayerId?'（房主）':'' }}</text><strong>{{ p.ready?'已准备':'未准备' }}</strong></view></view><text v-if="snapshot.status==='COUNTDOWN'" class="rpg-room__count">{{ countdown }}</text><view class="rpg-room__actions"><button @click="ready">{{ selfReady?'取消准备':'我已准备' }}</button><button v-if="isHost" :disabled="!canStart" class="rpg-room__start" @click="start">开始训练</button></view><text class="rpg-room__tip">全员准备后统一倒计时，随后进入膝关节零位校准</text></view></view></template>
<script lang="ts">
import type { RoomSnapshot } from '../../../game-platform/multiplayer/types';import { beginPenaltyMultiplayer,getPenaltyMultiplayerClient,leavePenaltyRoom } from '../../runtime/multiplayer-runtime';import { appendReturnUrl,configureCallerReturnUrl,returnToCaller } from '../../../game-platform/runtime/navigation';import { getViewportLayout,viewportStyle } from '../../../game-platform/runtime/viewport'
export default{name:'RpgRoom',data(){return{snapshot:null as RoomSnapshot|null,unsubscribe:null as (()=>void)|null,timer:null as ReturnType<typeof setInterval>|null,now:Date.now(),navigating:false,leaving:false,viewport:getViewportLayout()}},computed:{selfId():string{return getPenaltyMultiplayerClient()?.bootstrap.identity.playerId??''},selfReady():boolean{return this.snapshot?.players.find(p=>p.playerId===this.selfId)?.ready??false},isHost():boolean{return this.snapshot?.hostPlayerId===this.selfId},canStart():boolean{return!!this.snapshot&&this.snapshot.players.length>=2&&this.snapshot.players.every(p=>p.ready&&p.connected)},countdown():string{return this.snapshot?.startsAtMs?String(Math.max(1,Math.ceil((this.snapshot.startsAtMs-this.now)/1000))):'3'},viewportCss():Record<string,string>{return viewportStyle(this.viewport,'--rpg-safe-top')}},onLoad(q:Record<string,string|undefined>){configureCallerReturnUrl(q?.returnUrl,'/pages-penalty-game/home/index');const c=getPenaltyMultiplayerClient();if(!c?.store.getSnapshot()){this.leaving=true;uni.showToast({title:'房间已退出',icon:'none'});returnToCaller();return}this.unsubscribe=c.store.subscribe(s=>{this.snapshot=s;if(s?.status==='RUNNING'&&!this.navigating){if(!beginPenaltyMultiplayer())return;this.navigating=true;uni.redirectTo({url:appendReturnUrl('/pages-penalty-game/calibrate/index?multiplayer=1')})}});this.timer=setInterval(()=>{this.now=c.serverNowMs()},100)},onResize(){this.viewport=getViewportLayout()},onBackPress(){this.leave();return true},onUnload(){this.unsubscribe?.();if(this.timer)clearInterval(this.timer);if(!this.navigating&&!this.leaving)leavePenaltyRoom()},methods:{ready(){getPenaltyMultiplayerClient()?.setReady(!this.selfReady)},start(){getPenaltyMultiplayerClient()?.startRoom()},leave(){if(this.leaving||this.navigating)return;this.leaving=true;leavePenaltyRoom();returnToCaller({delta:1})}}}
</script>
<style scoped>.rpg-room{display:flex;align-items:center;justify-content:center;box-sizing:border-box;min-height:100vh;padding:calc(var(--rpg-safe-top,8px) + 10px) 20px;background:linear-gradient(145deg,#dff4ff,#fff2bf);font-family:"Microsoft YaHei",sans-serif;color:#24516e}.rpg-room__card{width:min(560px,94vw);padding:24px;border:3px solid #2a89ca;border-radius:22px;background:#fff}.rpg-room__back{display:flex;align-items:center;justify-content:center;height:40px;margin:0 0 12px;padding:0 14px;border:0;border-radius:999px;background:#e7f4fc;color:#2471a4}.rpg-room__header{display:flex;align-items:center;justify-content:space-between}.rpg-room__header view text,.rpg-room__header strong{display:block}.rpg-room__header view text{color:#0878c9;font-size:30px;font-weight:900}.rpg-room__players{margin:15px 0}.rpg-room__players view{display:flex;justify-content:space-between;padding:10px;border-bottom:1px solid #d5e9f4}.rpg-room__players strong{color:#2e9d50}.rpg-room__count{display:block;color:#f19919;font-size:64px;font-weight:900;text-align:center}.rpg-room__actions{display:flex;gap:12px}.rpg-room__actions button{flex:1;margin:0;border:0;border-radius:13px;background:#e2f2fc;color:#2674a6;font-weight:900}.rpg-room__actions .rpg-room__start{background:#ffc729;color:#714500}.rpg-room__tip{display:block;margin-top:12px;text-align:center;font-size:12px;color:#718593}</style>
